const docs = $('Convert To Json Structured Data').all();
return [{ json: {
  status: 'Insertion loop completed',
  source_file: docs[0]?.json.source_file || '',
  source_records: docs.length,
  unique_source_test_case_ids: new Set(docs.map(item => item.json.tc_id)).size,
  source_records_with_summary: docs.filter(item => item.json.summary).length,
  namespace: 'wingify-login-v2',
  note: 'These are source counts, not an independent Pinecone count. Inspect stored records and test retrieval. Upload once per fresh namespace; repeat insertion can create duplicates.'
} }];

const items = $input.all();
if (items.length !== 1) throw new Error('Upload exactly one CSV file per run.');
const item = items[0];
const keys = Object.keys(item.binary || {});
if (keys.length !== 1) throw new Error('Upload exactly one CSV file.');
const file = item.binary[keys[0]];
if (!String(file.fileName || '').toLowerCase().endsWith('.csv')) {
  throw new Error('This workflow accepts the test-case CSV. Export an Excel worksheet as CSV first.');
}
return [{ json: { source_file: file.fileName }, binary: { data: file }, pairedItem: { item: 0 } }];

const required = ['Test Case ID', 'Summary', 'Preconditions', 'Test Data', 'Test Steps', 'Expected Result'];
const fields = ['Test Case ID', 'Summary', 'Category', 'Scenario Type', 'Priority', 'Preconditions', 'Test Data', 'Test Steps', 'Expected Result', 'Execution Status', 'Assumptions / Applicability'];
const seen = new Set();
const items = $input.all();
if (!items.length) throw new Error('No CSV records were extracted.');
const sourceFile = $('Convert To Json Bulk Binary Data').first().json.source_file;
return items.map((item, index) => {
  const row = Object.fromEntries(Object.entries(item.json).map(([key, value]) => [key.replace(/^\uFEFF/, '').trim(), value]));
  const get = (key) => row[key] == null ? '' : String(row[key]).trim();
  const missing = required.filter(key => !get(key));
  if (missing.length) throw new Error(`CSV record ${index + 1}: missing ${missing.join(', ')}. Check headers and field mapping.`);
  const tcId = get('Test Case ID');
  if (seen.has(tcId)) throw new Error(`Duplicate Test Case ID in upload: ${tcId}`);
  seen.add(tcId);
  const text = fields.filter(key => get(key)).map(key => `${key}: ${get(key)}`).join('\n\n');
  if (text.length > 1000) {
    throw new Error(`${tcId} has ${text.length} characters. To retain a complete case, raise this limit AND the splitter chunkSize together before ingestion. No truncation was performed.`);
  }
  return {
    json: {
      text, tc_id: tcId, summary: get('Summary'), category: get('Category'),
      scenario_type: get('Scenario Type'), priority: get('Priority'),
      test_type: get('Test Type'), execution_status: get('Execution Status'),
      environment: get('Environment'), source_file: sourceFile, document_type: 'test_case'
    },
    pairedItem: { item: index }
  };
});
